def sha256(path: Path) -> str | None:
    if not path.exists():
        return None
    return hashlib.sha256(path.read_bytes()).hexdigest()


def find_root(explicit: str | None) -> Path:
    candidates = []
    if explicit:
        candidates.append(Path(explicit))
    candidates.extend([Path.cwd(), Path.cwd().parent, Path(__file__).resolve().parent.parent])
    for root in candidates:
        if (root / "jessica" / "core" / "models.py").is_file() and (root / "tests").is_dir():
            return root.resolve()
    raise SystemExit("Raiz do projeto nao encontrada. Use --root CAMINHO.")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root")
    parser.add_argument("--test", action="store_true")
    args = parser.parse_args()
    root = find_root(args.root)

    states = {}
    unknown = []
    for relative, item in PAYLOAD.items():
        current = sha256(root / relative)
        if current == item["after"]:
            states[relative] = "done"
        elif current == item["before"]:
            states[relative] = "apply"
        else:
            unknown.append(relative)
    if unknown:
        print("ABORTADO: arquivos com versao inesperada:")
        for relative in unknown:
            print(f"  - {relative}")
        return 2

    pending = [relative for relative, state in states.items() if state == "apply"]
    if not pending:
        print("v5v11 ja aplicado; nenhum arquivo alterado.")
    else:
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup = root / "backups" / f"v5v11_systems_{stamp}"
        for relative in pending:
            target = root / relative
            if target.exists():
                saved = backup / relative
                saved.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(target, saved)
        for relative in pending:
            target = root / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            data = zlib.decompress(base64.b85decode(PAYLOAD[relative]["data"]))
            temporary = target.with_name(target.name + ".v5v11.tmp")
            temporary.write_bytes(data)
            temporary.replace(target)
        print(f"v5v11 aplicado em {root}")
        print(f"Backup: {backup}")

    source = Path(__file__).resolve()
    saved_script = root / "fixes" / source.name
    if source != saved_script:
        saved_script.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, saved_script)

    if args.test:
        result = subprocess.run([sys.executable, str(root / "tests" / "run_all.py")], cwd=root)
        return result.returncode
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
